INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q2334663', 'Ancient Estonia', 'Ancient Estonia is the prehistoric period in the history of Estonia that concerns the emergence of human settlement in the area of what is now modern-day Estonia. It follows the period in the history of Estonia from the middle of the 8th millennium BC (around 8000 BC) until the conquest and subjugation of the local Finnic tribes in the first quarter of the until the 13th century during the Teutonic and Danish Northern Crusades during the Middle Ages.', -8000, NULL, NULL, 1300, NULL, NULL, 'millennium', '8th millennium BCE – 13th century', 51, 'https://en.wikipedia.org/wiki/Ancient_Estonia'),
  ('Q3736445', 'Battle of Viljandi', 'The Battle of Viljandi was a battle during the Livonian Crusade in 1211 in Viljandi, Estonia. The battle ended with no decisive victory for the invaders as they were unable to take the stronghold.', 1211, 3, NULL, NULL, NULL, NULL, 'month', 'March 1211', 37, 'https://en.wikipedia.org/wiki/Battle_of_Viljandi'),
  ('Q396501', 'Battle of Lehola', 'The Battle of Lehola was fought in 1215 between the Livonian Brothers of the Sword, a crusading military order, and the Estonians.', 1215, NULL, NULL, NULL, NULL, NULL, 'year', '1215', 37, 'https://en.wikipedia.org/wiki/Battle_of_Lehola'),
  ('Q1082410', 'Battle of St. Matthew''s Day', 'The Battle of Matthew''s Day (Estonian: Madisepäeva lahing) was fought near Viljandi (probably in Vanamõisa) on 21 September 1217 during the Livonian Crusade. The adversaries were the Sword Brethren (a German Crusading order) with their recently converted Livonian and Latgalian allies versus an army of 6,000 Estonian men from different counties, led by Lembitu, who had attempted to unify the Estonians.', 1217, 9, 21, NULL, NULL, NULL, 'day', '21 September 1217', 53, 'https://en.wikipedia.org/wiki/Battle_of_St._Matthew''s_Day'),
  ('Q3739195', 'Battle of Otepää', 'The Battle of Otepää (Russian: Битва при Оденпе) was a battle during the Livonian Crusade in February 1217. The battle ended in a compromise, with the Russians allowing the Germans to leave the fortress.', 1217, 2, NULL, NULL, NULL, NULL, 'month', 'February 1217', 34, 'https://en.wikipedia.org/wiki/Battle_of_Otep%C3%A4%C3%A4'),
  ('Q1341824', 'Battle of Lyndanisse', 'The Battle of Lyndanisse or Lindanise was fought on 15 June 1219 during the North Crusades, between the forces of the invading Kingdom of Denmark and the local non-Christian Estonians. The Danish victory in the battle, at the site of the later Hanseatic city of Reval (now Tallinn, Estonia) helped King Valdemar II of Denmark to subsequently claim the territory of northern Estonia as his participation in the crusade into Estonia had been undertaken in response to calls from the Pope.', 1219, 6, 15, NULL, NULL, NULL, 'day', '15 June 1219', 61, 'https://en.wikipedia.org/wiki/Battle_of_Lyndanisse'),
  ('Q2692278', 'Battle of Lihula', 'The Battle of Lihula or Battle of Leal was fought between invading Swedes and Estonians for the control of a castle in Lihula, Estonia in 1220. The exact date remains uncertain, though some historians suggest that the battle took place on August 8.', 1220, 8, 8, NULL, NULL, NULL, 'day', '8 August 1220', 48, 'https://en.wikipedia.org/wiki/Battle_of_Lihula'),
  ('Q3738423', 'Siege of Tartu', 'The siege of Tartu, or Dorpat, took place in 1224 and resulted in the fall of the last major center of Estonian resistance in the mainland provinces to the Christian conquest of Estonia.', 1224, 8, 15, NULL, NULL, NULL, 'day', '15 August 1224', 37, 'https://en.wikipedia.org/wiki/Siege_of_Tartu_(1224)'),
  ('Q3738385', 'Battle of Muhu', 'The Battle of Muhu was a military engagement fought between a force of Baltic and Germanic crusaders and pagan Oeselians. The battle, fought in Muhu, Estonia, resulted in the crusaders storming and capturing a fortress held by the Oeselians.', 1227, 1, 1, NULL, NULL, NULL, 'day', '1 January 1227', 37, 'https://en.wikipedia.org/wiki/Battle_of_Muhu'),
  ('Q252698', 'Battle of Wesenberg', 'The Battle of Wesenberg, Rakvere, or Rakovor, was fought on 18 February 1268 between the combined forces of Danish Estonia, the Bishopric of Dorpat, the Livonian Order, and local Estonian militias on one side, and the combined Russian forces of Novgorod and Pskov, led by Dmitry of Pereslavl, on the other. Medieval accounts of the battle vary, with both sides claiming victory.', 1268, 2, 28, NULL, NULL, NULL, 'day', '28 February 1268', 58, 'https://en.wikipedia.org/wiki/Battle_of_Wesenberg_(1268)'),
  ('Q4337412', 'Siege of Narva', 'The siege of Narva (Estonian: Narva piiramine; Russian: Осада Нарвы) was a Russian siege of the Livonian city of Narva (in modern-day eastern Estonia) from April through May 1558, during the Livonian War. After capturing the city in July 1558, the Russians used Narva as a trading center and port to move goods from Pskov and Novgorod.', 1558, NULL, NULL, 1558, 5, NULL, 'year', '1558', 37, 'https://en.wikipedia.org/wiki/Siege_of_Narva_(1558)'),
  ('Q2918454', 'Estonia under Swedish rule', 'Estonia under Swedish rule signifies the period of time between 1561 and 1710, when present-day Estonia was under the rule of the Swedish Empire. In the wake of the breakup of the State of the Teutonic Order, the Baltic German local nobility in the areas of Harrien (Harjumaa) and Wierland (Virumaa), as well as the city of Reval (Tallinn) in June 1561 and somewhat later Jerwen (Järvamaa), asked for and were granted protection by the Swedish king Eric XIV, leading to Swedish involvement in the Livonian War.', 1561, NULL, NULL, 1710, NULL, NULL, 'year', '1561–1710', 43, 'https://en.wikipedia.org/wiki/Estonia_under_Swedish_rule'),
  ('Q2063447', 'Battle of Lode', 'The Battle of Lode was fought during the Livonian War, between a Swedish and Russian army on 23 January 1573, near the town of Lode (now Koluvere). The battle was won by the Swedes.', 1573, 1, 23, NULL, NULL, NULL, 'day', '23 January 1573', 41, 'https://en.wikipedia.org/wiki/Battle_of_Lode'),
  ('Q7510514', 'Siege of Wesenberg', 'The siege of Wesenberg, Rakvere, or Rakovor, was an abortive Swedish siege of the Russian-held town of Wesenberg in Estonia from January through March 1574, during the Livonian War. The siege is infamous for a brawl and subsequent combat between German and Scottish mercenaries within the besieging army, which claimed the lives of about 1,500 Scots.', 1574, 1, NULL, 1574, 3, NULL, 'month', 'January 1574 – March 1574', 41, 'https://en.wikipedia.org/wiki/Siege_of_Wesenberg_(1574)'),
  ('Q598774', 'Polish–Swedish War of 1600–11', 'The Polish–Swedish War (1600–1611) was a continuation of struggle between Sweden and the Polish–Lithuanian Commonwealth over control of Livonia and Estonia, as well as the dispute over the Swedish throne between Charles IX of Sweden and Sigismund III of Poland. After skirmishes, sieges and battles often aborted by Jan Karol Chodkiewicz, a truce was signed until the later invasion by the Russians.', 1600, NULL, NULL, 1611, NULL, NULL, 'year', '1600–1611', 61, 'https://en.wikipedia.org/wiki/Polish%E2%80%93Swedish_War_(1600%E2%80%931611)'),
  ('Q16822637', 'Battle of Karksi', 'The Battle of Karksi (also known as Battle of Karkus) was fought during the Polish–Swedish War (1600–1611) between the Polish–Lithuanian Commonwealth and the Kingdom of Sweden on 29 October 1600.', 1600, 10, 29, NULL, NULL, NULL, 'day', '29 October 1600', 41, 'https://en.wikipedia.org/wiki/Battle_of_Karksi_(1600)'),
  ('Q775401', 'Battle of Reval', 'The Battle of Reval took place on June 30, 1602, during the Polish–Swedish War (1600–1611) near present-day Tallinn in Estonia.', 1602, 6, 30, NULL, NULL, NULL, 'day', '30 June 1602', 41, 'https://en.wikipedia.org/wiki/Battle_of_Reval_(1602)'),
  ('Q2330878', 'Siege of Weissenstein', 'The siege of Weissenstein took place between 31 May and 30 September 1602, during the Polish–Swedish War of 1600–1611. Two weeks after the capture of Fellin, Grand Crown Hetman Jan Zamoyski led the Polish-Lithuanian army of 2,000 troops to besiege Weissenstein (now known as Paide in Estonia).', 1602, 5, 31, 1602, 9, 30, 'day', '31 May 1602 – 30 September 1602', 39, 'https://en.wikipedia.org/wiki/Siege_of_Weissenstein'),
  ('Q4337460', 'Siege of Fellin', 'The siege of Fellin took place between 25 March and 17 May 1602 during the Polish–Swedish War (1600–1611). Polish and Lithuanian forces led by Grand Crown Hetman Jan Zamoyski besieged the Swedish-held town of Fellin (present-day Viljandi in Estonia).', 1602, 3, 25, 1602, 5, 17, 'day', '25 March 1602 – 17 May 1602', 39, 'https://en.wikipedia.org/wiki/Siege_of_Fellin'),
  ('Q4087364', 'Battle of Rakvere', 'The Battle of Rakvere took place on 5 March 1603 during the Polish–Swedish War (1600–1611). In December, 1602, the siege of Dorpat commenced.', 1603, 3, 5, NULL, NULL, NULL, 'day', '5 March 1603', 39, 'https://en.wikipedia.org/wiki/Battle_of_Rakvere_(1603)'),
  ('Q643027', 'Battle of Weissenstein', 'The Battle of Weissenstein, or Battle of Biały Kamień, was fought during the Polish–Swedish War (1600–1611), between Sweden and the Polish–Lithuanian Commonwealth on 25 September 1604. The Swedish army was commanded by Arvid Stålarm and the Polish army under Jan Karol Chodkiewicz.', 1604, 9, 25, NULL, NULL, NULL, 'day', '25 September 1604', 45, 'https://en.wikipedia.org/wiki/Battle_of_Weissenstein'),
  ('Q4110458', 'Siege of Pärnu', 'The siege of Pärnu (Polish: Parnawa) took place between February 28 and March 2, 1609 during the Polish–Swedish War (1600–1611). The Grand hetman of Lithuania Jan Karol Chodkiewicz, while resting his forces in Birże (Biržai), learned of Swedish deployments from Pärnu (present-day Estonia) moving towards Daugavgrīva (in present-day Latvia) and set out to cut these off.', 1609, 2, 28, 1609, 3, 2, 'day', '28 February 1609 – 2 March 1609', 37, 'https://en.wikipedia.org/wiki/Siege_of_P%C3%A4rnu'),
  ('Q1456449', 'Treaty of Cardis', 'The Treaty of Cardis was a peace settlement made in 1661 between the Tsardom of Russia and the Swedish Empire. This particular agreement ended the Russo-Swedish War of 1656–1658.', 1661, 6, 21, NULL, NULL, NULL, 'day', '21 June 1661', 56, 'https://en.wikipedia.org/wiki/Treaty_of_Cardis'),
  ('Q481518', 'Battle of Rauge', 'The Battle of Rauge took place on 15 September 1701 near Rõuge, Livonia during the Great Northern War in which the Swedes defeated the numerically superior Russians.', 1701, 9, 4, NULL, NULL, NULL, 'day', '4 September 1701', 37, 'https://en.wikipedia.org/wiki/Battle_of_Rauge'),
  ('Q620947', 'Battle of Hummelshof', 'Battle of Hummelshof took place on 18 July 1702 (O.S.) near the small town Hummelshof in Swedish Livonia (present-day Estonia). It was the second significant Russian victory in the Great Northern War in which a Russian army under Boris Sheremetev attacked a much smaller force under Wolmar Anton von Schlippenbach and defeated it after experiencing similar casualties to the Swedes.', 1702, 7, 29, NULL, NULL, NULL, 'day', '29 July 1702', 48, 'https://en.wikipedia.org/wiki/Battle_of_Hummelshof'),
  ('Q694883', 'Battle of Erastfer', 'The Battle of Erastfer (also Battle of Errestfer, Battle of Erastvere) took place on 29 December 1701 (O.S.) / 30 December 1701 (Swedish calendar) / 9 January / 1702 (N.S.) near Erastfer in eastern Swedish Livonia (present-day Erastvere in Estonia) between a Russian force of around 13,000 regulars along with 6,000 irregulars led by general Boris Sheremetev and a Swedish force of about 3,470 men (at least 1,000 men were absent from the ranks for various reasons on the day of the battle, resulting in an actual fighting force of about 2,200–2,470 men), under the command of Wolmar Anton von…', 1702, 1, 9, NULL, NULL, NULL, 'day', '9 January 1702', 47, 'https://en.wikipedia.org/wiki/Battle_of_Erastfer'),
  ('Q694054', 'Siege of Narva', 'The siege of Narva (Russian: Осада Нарвы, Swedish: Belägringen av Narva), also known as the second battle of Narva, was the second Russian siege of Swedish Narva during the Great Northern War from 8 July to 20 August 1704.', 1704, 6, 27, 1704, 8, 9, 'day', '27 June 1704 – 9 August 1704', 56, 'https://en.wikipedia.org/wiki/Siege_of_Narva_(1704)'),
  ('Q2237139', 'Battle of Wesenberg', 'The Battle of Wesenberg took place on 26 June 1704 close to Rakvere (Wesenberg) during the Great Northern War. The Swedish cavalry force of 1,400 men under the command of Wolmar Anton von Schlippenbach retreated before Carl Ewald von Rönnes larger force.', 1704, 6, 15, NULL, NULL, NULL, 'day', '15 June 1704', 34, 'https://en.wikipedia.org/wiki/Battle_of_Wesenberg_(1704)'),
  ('Q2495510', 'Battle of Reval', 'The Battle of Reval took place on 13 May [O.S. 2 May] 1790 during the Russo-Swedish War of 1788–1790, off the port of Reval in the roadstead (now Tallinn, Estonia). This battle ended in an imposing Imperial Russian Navy victory; it has been compared to the practice of running the gauntlet.', 1790, 5, 13, NULL, NULL, NULL, 'day', '13 May 1790', 43, 'https://en.wikipedia.org/wiki/Battle_of_Reval'),
  ('Q2918340', 'German occupation of Estonia during World War I', 'Estonia was under military occupation by the German Empire during the later stages of the First World War. On 11–21 October 1917, the Imperial German Army occupied the West Estonian archipelago (Moonsund archipelago), including the larger islands of Saaremaa (Ösel), Hiiumaa (Dagö), and Muhu (Moon).', 1917, NULL, NULL, 1918, NULL, NULL, 'year', '1917–1918', 58, 'https://en.wikipedia.org/wiki/German_occupation_of_Estonia_during_World_War_I'),
  ('Q1127302', 'Estonian War of Independence', 'The Estonian War of Independence, also known as the Estonian Liberation War, and War of Freedom in Estonia, was a defensive campaign of the Estonian Army and its allies, most notably the United Kingdom and Finland, against the Soviet Russian westward offensive of 1918–1919 and the 1919 aggression of the pro–German Baltische Landeswehr. The campaign was the struggle of the newly established democratic state of Estonia for independence in the aftermath of World War I. It resulted in a victory for Estonia and was concluded in the 1920 Treaty of Tartu.', 1918, 11, 28, 1920, 1, 3, 'day', '28 November 1918 – 3 January 1920', 73, 'https://en.wikipedia.org/wiki/Estonian_War_of_Independence'),
  ('Q2174038', 'Interwar Estonia', 'The history of Estonia from 1920 to 1939 spanned the interwar period from the end of the Estonian War of Independence until the outbreak of World War II. It covers the years of parliamentary democracy, the Great Depression and the period of corporatist authoritarian rule. The Estonian state, as it existed throughout the interwar period until the Soviet occupation and the creation of the Estonian SSR, is sometimes dubbed the First Republic of Estonia, but this terminology is often avoided for two main reasons: Most countries recognise the legal continuity between the state declared in 1918,…', 1918, NULL, NULL, 1940, NULL, NULL, 'year', '1918–1940', 55, 'https://en.wikipedia.org/wiki/History_of_Estonia_(1920%E2%80%931939)'),
  ('Q3089540', 'Soviet westward offensive of 1918–1919', 'The Soviet westward offensive of 1918–1919 was part of the campaign by Soviet Russia into areas abandoned by the Ober Ost garrisons that were being withdrawn to Germany following that country''s defeat in World War I. The initially successful offensive against the Republic of Estonia ignited the Estonian War of Independence which ended with the Soviet recognition of Estonia. Similarly, the campaigns against the Republic of Latvia and Republic of Lithuania ultimately failed, resulting in the Latvian–Soviet Peace Treaty and Soviet–Lithuanian Peace Treaty respectively.', 1918, 11, 18, 1919, 3, NULL, 'day', '18 November 1918 – March 1919', 52, 'https://en.wikipedia.org/wiki/Soviet_westward_offensive_of_1918%E2%80%931919'),
  ('Q1720027', 'Battle of Paju', 'The Battle of Paju (Estonian: Paju lahing) was fought in Paju, near Valga, Estonia, on 31 January 1919 during the Estonian War of Independence. After heavy fighting, the Tartu-Valga group of the Estonian Army pushed the Red Latvian Riflemen out of the Paju Manor.', 1919, 1, 31, NULL, NULL, NULL, 'day', '31 January 1919', 48, 'https://en.wikipedia.org/wiki/Battle_of_Paju'),
  ('Q3495333', 'Battle of Utria', 'Battle of Utria (Estonian: Utria Lahing) also known as the Utria Landing (Estonian: Utria Dessant) took place during the Estonian War of Independence on 17–20 January 1919 at Udria beach. It was an amphibious landing consisting mainly of Finnish volunteers.', 1919, 1, 17, 1919, 1, 20, 'day', '17 January 1919 – 20 January 1919', 41, 'https://en.wikipedia.org/wiki/Battle_of_Utria'),
  ('Q3509192', 'Battle of Laagna', 'Battle of Laagna (Estonian: Laagna lahing; 17 January 1919) took place in Laagna, Estonia, during the Estonian War of Independence. A battalion of Estonian marines and four companies of Finnish volunteers under the overall command of Martin Ekström attacked Red Army positions at Laagna as part of a wider operation targeting Narva.', 1919, 1, 18, NULL, NULL, NULL, 'day', '18 January 1919', 34, 'https://en.wikipedia.org/wiki/Battle_of_Laagna'),
  ('Q3509272', 'Battle of Krivasoo', 'Battle of Krivasoo (Estonian: Krivasoo lahing; 18 November 1919 - 30 December 1919) took place near the Krivasoo, Estonia during the Estonian War of Independence between the Estonian Army and the Red Army. It is considered one of the last engagements of the conflict before a ceasefire was called in early January 1920.', 1919, 11, 18, 1919, 12, 30, 'day', '18 November 1919 – 30 December 1919', 34, 'https://en.wikipedia.org/wiki/Battle_of_Krivasoo'),
  ('Q5401687', 'Estonian religious education referendum, 1923', 'A referendum on restoring voluntary religious education to state schools was held in Estonia between 17 and 19 February 1923. It was approved by 71.9% of voters with a turnout of 66.2%.', 1923, 2, 19, NULL, NULL, NULL, 'day', '19 February 1923', 37, 'https://en.wikipedia.org/wiki/1923_Estonian_religious_education_referendum'),
  ('Q1760435', '1934 Estonian coup d''état', 'The Estonian coup d''état of 1934 was a bloodless military coup organized on March 12, 1934, by State Elder candidates Johan Laidoner, Konstantin Päts, and August Rei, who took part in the State Elder elections scheduled for April of the same year, during which Lieutenant General Laidoner and acting State Elder Päts had several Vaps leaders and activists, supporters of the fourth State Elder candidate Andres Larka, arrested. Päts, in violation of the constitution, appointed Laidoner as the commander-in-chief of the defense forces and decreed a stop to the election process for State Elder and…', 1934, 3, 12, NULL, NULL, NULL, 'day', '12 March 1934', 41, 'https://en.wikipedia.org/wiki/1934_Estonian_coup_d''%C3%A9tat'),
  ('Q5384797', 'Era of Silence', 'The history of Estonia from 1920 to 1939 spanned the interwar period from the end of the Estonian War of Independence until the outbreak of World War II. It covers the years of parliamentary democracy, the Great Depression and the period of corporatist authoritarian rule. The Estonian state, as it existed throughout the interwar period until the Soviet occupation and the creation of the Estonian SSR, is sometimes dubbed the First Republic of Estonia, but this terminology is often avoided for two main reasons: Most countries recognise the legal continuity between the state declared in 1918,…', 1934, 3, 12, 1938, NULL, NULL, 'day', '12 March 1934 – 1938', 53, 'https://en.wikipedia.org/wiki/Era_of_Silence'),
  ('Q3739093', 'Soviet–Estonian Mutual Assistance Treaty', 'The Soviet–Estonian Mutual Assistance Treaty (Estonian: Eesti Vabariigi ja NSV Liidu vaheline vastastikuse abistamise pakt, Russian: Пакт о взаимопомощи между СССР и Эстонией, romanized: Pakt o vzaimopomoshchi mezhdu SSSR i Estoniyey), also known as the Bases Treaty (Estonian: baaside leping) was a bilateral treaty between the Soviet Union and Estonia, signed in Moscow on 28 September 1939. The treaty obliged both parties to respect each other''s sovereignty and independence, and allowed the Soviet government to establish military bases in Estonia.', 1939, 9, 28, NULL, NULL, NULL, 'day', '28 September 1939', 52, 'https://en.wikipedia.org/wiki/Soviet%E2%80%93Estonian_Mutual_Assistance_Treaty'),
  ('Q58473', 'occupation of the Baltic states', 'The Baltic states—Estonia, Latvia, and Lithuania—were occupied and annexed by the Soviet Union in 1940 and remained under its control until its dissolution in 1991. For a period of several years during World War II, Nazi Germany occupied the Baltic states after it invaded the Soviet Union in 1941.', 1940, NULL, NULL, 1991, NULL, NULL, 'year', '1940–1991', 69, 'https://en.wikipedia.org/wiki/Occupation_of_the_Baltic_states'),
  ('Q3738122', '1940 Estonian coup d''état', 'The 1940 Estonian coup d''état, also known as the June coup, or in Soviet historiography, the June Revolution of 1940, was the Soviet-backed replacement of the government of the Republic of Estonia on 21 June 1940. Following the issuance of an ultimatum to the Estonians on 16 June, Soviet troops occupied Estonia on 17 June.', 1940, 6, 21, NULL, NULL, NULL, 'day', '21 June 1940', 37, 'https://en.wikipedia.org/wiki/1940_Estonian_coup_d''%C3%A9tat'),
  ('Q15052924', 'Soviet occupation in Estonia', 'The Baltic states—Estonia, Latvia, and Lithuania—were occupied and annexed by the Soviet Union in 1940 and remained under its control until its dissolution in 1991. For a period of several years during World War II, Nazi Germany occupied the Baltic states after it invaded the Soviet Union in 1941.', 1940, 6, 16, 1940, 8, 6, 'day', '16 June 1940 – 6 August 1940', 37, 'https://en.wikipedia.org/wiki/Soviet_occupation_of_Estonia'),
  ('Q1324428', 'Baltic Operation', 'The Baltic strategic defensive operation (Russian: Прибалтийская стратегическая оборонительная операция, romanized: Pribaltiyskaya strategicheskaya oboronitel''naya operatsiya) encompassed the operations of the Red Army from 22 June to 9 July 1941 conducted over the territories of Soviet-occupied Lithuania, Latvia, and Estonia in response to the offensive launched by the Wehrmacht in Operation Barbarossa.', 1941, 7, 9, NULL, NULL, NULL, 'day', '9 July 1941', 56, 'https://en.wikipedia.org/wiki/Baltic_operation'),
  ('Q3322608', 'German occupation of Estonia during World War II', 'In the course of Operation Barbarossa, Nazi Germany invaded Estonia in July–December 1941, and occupied the country until 1944. Estonia had gained independence in 1918 from the then-warring German and Russian Empires.', 1941, NULL, NULL, 1944, NULL, NULL, 'year', '1941–1944', 51, 'https://en.wikipedia.org/wiki/German_occupation_of_Estonia_during_World_War_II'),
  ('Q7075770', 'German occupation of the Baltic states during World War II', 'After the German invasion of the Soviet Union, the Baltic states were under military occupation by Nazi Germany from 1941 to 1944. Initially, many Estonians, Latvians, and Lithuanians considered the Germans liberators from the Soviet Union.', 1941, 7, NULL, 1944, NULL, NULL, 'month', 'July 1941 – 1944', 37, 'https://en.wikipedia.org/wiki/German_occupation_of_the_Baltic_states_during_World_War_II'),
  ('Q12375607', 'Summer War', 'The Summer War (Estonian: Suvesõda) was the occupation of Estonia during the Second World War.', 1941, NULL, NULL, NULL, NULL, NULL, 'year', '1941', 43, 'https://en.wikipedia.org/wiki/Summer_War'),
  ('Q481578', 'Tallinn Offensive', 'The Tallinn offensive (Russian: Таллинская наступательная операция) was a strategic offensive by the Red Army''s 2nd Shock Army and 8th Army and the Baltic Fleet against the German Army Detachment Narwa and Estonian units in mainland Estonia on the Eastern Front of World War II on 17–26 September 1944. Its German counterpart was the abandonment of the Estonian territory in a retreat codenamed Operation Aster (German: Unternehmen Aster).', 1944, 9, 26, 1944, 9, 26, 'day', '26 September 1944', 51, 'https://en.wikipedia.org/wiki/Tallinn_offensive'),
  ('Q2008158', 'Moonsund Landing Operation', 'The Moonsund landing operation (Russian: Моонзундская десантная операция; Estonian: Lääne-Eesti saarte kaitsmine; Swedish: Moonsund Invasionen) was an amphibious operation and offensive by the Red Army during World War II, taking place in late 1944. It was part of the Baltic offensive, and was designed to clear German forces of Army Group North from the islands in East Baltic Sea, the West Estonian archipelago (Moonsund archipelago).', 1944, 9, 29, 1944, 11, 24, 'day', '29 September 1944 – 24 November 1944', 47, 'https://en.wikipedia.org/wiki/Moonsund_operation'),
  ('Q2026904', 'Battle of Tannenberg Line', 'The Battle of Tannenberg Line (German: Die Schlacht um die Tannenbergstellung; Russian: Битва за линию «Танненберг») or the Battle of the Blue Hills (Estonian: Sinimägede lahing) was a military engagement between the German Army Detachment Narwa and the Soviet Leningrad Front. They fought for the strategically important Narva Isthmus from 25 July–10 August 1944.', 1944, 7, 25, 1944, 8, 10, 'day', '25 July 1944 – 10 August 1944', 53, 'https://en.wikipedia.org/wiki/Battle_of_Tannenberg_Line'),
  ('Q2065459', 'Battle of Tehumardi', 'The Battle of Tehumardi (Estonian: Tehumardi öölahing, Russian: Бой у Техумарди, German Schlacht von Tehumardi) was a battle on October 8, 1944, related to the Moonsund Operation during World War II. Soviet soldiers fought German troops occupying Tehumardi. It was one of the most brutal engagements during the fighting on the Estonian island of Saaremaa (Ösel) in 1944.', 1944, 10, 8, NULL, NULL, NULL, 'day', '8 October 1944', 39, 'https://en.wikipedia.org/wiki/Battle_of_Tehumardi'),
  ('Q4872082', 'Battle of Porkuni', 'Battle of Porkuni (Estonian: Porkuni lahing) was the largest engagement between Estonians serving in the Red Army and Estonian pro-independence and Waffen-SS units. It took place on 21 September 1944 between Lake Porkuni and the village of Sauvälja about seven kilometres northeast of the town of Tamsalu during the Leningrad Front''s Tallinn Offensive Operation (17 September 1944 – 26 September 1944).', 1944, 9, 21, NULL, NULL, NULL, 'day', '21 September 1944', 41, 'https://en.wikipedia.org/wiki/Battle_of_Porkuni'),
  ('Q6966495', 'March 1944 Narva Offensive', 'The Narva offensive (1–4 March 1944) (Estonian: Putki lahing) was an operation conducted by the Soviet Leningrad Front. It was aimed at the conquest of the Narva Isthmus from the German army detachment "Narwa".', 1944, 3, 1, 1944, 3, 4, 'day', '1 March 1944 – 4 March 1944', 37, 'https://en.wikipedia.org/wiki/Narva_offensive_(1%E2%80%934_March_1944)'),
  ('Q7885422', 'Battle for Narva', 'The Battle of Narva was a World War II military campaign, lasting from 2 February to 10 August 1944, in which the German Army Detachment "Narwa" and the Soviet Leningrad Front fought for possession of the strategically important Narva Isthmus. The battle took place in the northern section of the Eastern Front and consisted of two major phases: the Battle for Narva Bridgehead (February to July 1944), and the Battle of Tannenberg Line (July–August 1944).', 1944, NULL, NULL, 1944, 8, 10, 'year', '1944', 61, 'https://en.wikipedia.org/wiki/Battle_of_Narva_(1944)'),
  ('Q15197058', 'Battle for Narva Bridgehead', 'The Battle of Narva Bridgehead (Estonian: Narva lahingud, German: Schlacht um den Brückenkopf von Narva, Russian: Битва за плацдарм Нарва; 2 February – 26 July 1944) was the campaign that stalled the Soviet Estonian operation in the surroundings of the town of Narva for six months. It was the first phase of the Battle of Narva campaign fought at the Eastern Front during World War II, the second phase being the Battle of Tannenberg Line.', 1944, 2, 2, 1944, 7, 26, 'day', '2 February 1944 – 26 July 1944', 37, 'https://en.wikipedia.org/wiki/Battle_for_Narva_Bridgehead'),
  ('Q595321', 'Singing Revolution', 'The Singing Revolution was a series of events from 1987 to 1991 that led to the restoration of independence of the three Soviet-occupied Baltic countries of Estonia, Latvia, and Lithuania at the end of the Cold War. The Soviet Union annexed the Baltics around 1940, following the Molotov-Ribbentrop Pact (a non-aggression agreement with Nazi Germany), though this annexation was not widely recognized.', 1987, NULL, NULL, 1991, NULL, NULL, 'year', '1987–1991', 73, 'https://en.wikipedia.org/wiki/Singing_Revolution'),
  ('Q16631950', 'Estonian restoration of Independence', 'Estonian Restoration of Independence, legally defined as the Restoration of the Republic of Estonia, was proclaimed on 20 August 1991. On that day at 23:02 local time, the Supreme Council of the Republic of Estonia, in agreement with the Estonian Committee (the executive organ of the Congress of Estonia), declared the illegal Soviet occupation and annexation of the country terminated, and proclaimed the full restoration of the independence of Estonia.', 1991, 8, 20, NULL, NULL, NULL, 'day', '20 August 1991', 45, 'https://en.wikipedia.org/wiki/Estonian_Restoration_of_Independence'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe');
